+                className="min-w-0 overflow-hidden whitespace-nowrap"
+              >
+                ********************************
+              </span>
+              <span className="shrink-0">{virtualRow.index + 1}. row</span>
+              <span
+                aria-hidden
+                className="min-w-0 overflow-hidden whitespace-nowrap"
+              >
+                ********************************
+              </span>
+            </p>
+            {renderRow(virtualRow.index)}
+          </div>
+        ))}
+      </div>
+    </div>
+  );
+});
