+	_, err = h.getMetadataInstance(ctx, common.FormatProjectInstance("project-b", instanceID))
+	require.Error(t, err)
+
+	_, err = db.ExecContext(ctx, "UPDATE project SET deleted = TRUE WHERE resource_id = $1", projectID)
