+const renderIntoContainer = (element: ReactElement) => {
+  const container = document.createElement("div");
+  const root = createRoot(container);
+
+  return {
+    container,
+    render: () =>
+      act(() => {
+        root.render(element);
+      }),
+    unmount: () =>
+      act(() => {
+        root.unmount();
+      }),
+  };
+};
