+// compositeTypesEqual checks attributes (order-sensitive) and comments.
+func compositeTypesEqual(oldComposite, newComposite *storepb.CompositeTypeMetadata) bool {
+	if oldComposite.Comment != newComposite.Comment {
+		return false
