+ * shape check, so malformed entries (empty strings, paths missing the
+ * `/{view}` root prefix) must be treated as inert — never as subfolders.
+ */
+export const isSubFolder = ({
+  parent,
+  path,
+  dig,
+}: {
+  parent: string;
+  path: string;
+  dig: boolean;
