+  const parentPrefix = `${parent}/`;
+  if (path === parentPrefix || !path.startsWith(parentPrefix)) {
+    return false;
+  }
+  if (dig) {
+    return true;
+  }
+  return !path.slice(parentPrefix.length).includes("/");
+};

