+
+const project = {
+  name: "projects/sample",
+  title: "Sample Project",
+  labels: {},
+} as Project;
+
+describe("ProjectTable", () => {
+  let container: HTMLDivElement;
+  let root: ReturnType<typeof createRoot>;
+
+  beforeEach(() => {
+    container = document.createElement("div");
+    document.body.append(container);
