+        if (!window.confirm(t("common.leave-without-saving"))) {
+          next(false);
+          return;
+        }
+      }
+      next();
+    });
+
+    return () => {
+      window.removeEventListener("beforeunload", handleBeforeUnload);
+      removeGuard();
+    };
+  }, [t]);
