+  useDatabaseV1Store: () => ({
+    getDatabaseByName: mocks.getDatabaseByName,
+  }),
+  useInstanceV1Store: () => ({
+    getInstanceByName: mocks.getInstanceByName,
+  }),
+}));
+
+vi.mock("@/react/components/EngineIcon", () => ({
