+						Right: &catalog.ConstExpr{
+							Value: "items",
+						},
+					}},
+				}},
+			}},
+		}
+		extractor := newOmniQuerySpanExtractor(loaderTestDB, []string{loaderTestSchema}, base.GetQuerySpanContext{})
