+    `ALTER TABLE employee ADD COLUMN IF NOT EXISTS ${columnName} TEXT;`
+  );
+
+  const specId = `spec-${Date.now()}`;
+  const plan = await env.api.createPlan(
+    env.project,
+    `E2E Approval Blocker Test ${Date.now()}`,
