+      "ProjectGitOpsPage",
+      pageProps
+    );
+  } else {
+    await updateReactPage(root, "ProjectGitOpsPage", pageProps);
+  }
+}
+
+onMounted(() => render());
+watch(locale, () => render());
+watch(
