+  );
+
+  useEffect(() => {
+    fetchInstances("");
+  }, [fetchInstances]);
+
+  const handleChange = useCallback(
+    (name: string) => {
+      const inst = instances.find((i) => i.name === name);
+      onChange(name, inst);
+    },
+    [instances, onChange]
+  );
