+            />
+            {inst.title}
+          </span>
+        );
+      }}
+      options={instances.map((inst) => ({
+        value: inst.name,
+        label: inst.title,
+        description: extractInstanceResourceName(inst.name),
+        render: () => (
+          <div className="flex flex-col gap-0.5">
+            <div className="flex items-center gap-1.5">
+              {inst.environment && (
