+// ============================================================
+// PortaledDropdown — renders dropdown via portal to avoid
+// overflow clipping and z-index issues inside dialogs
+// ============================================================
+
+function useClickOutside(
+  refs: React.RefObject<HTMLElement | null>[],
+  open: boolean,
+  onClose: () => void
+) {
+  const refsRef = useRef(refs);
+  refsRef.current = refs;
+  useEffect(() => {
+    if (!open) return;
+    const handler = (e: MouseEvent) => {
+      const target = e.target as Node;
+      if (refsRef.current.every((r) => !r.current?.contains(target))) {
+        onClose();
+      }
+    };
+    document.addEventListener("mousedown", handler);
+    return () => document.removeEventListener("mousedown", handler);
+  }, [open, onClose]);
+}
+
+function PortaledDropdown({
+  anchorRef,
+  dropdownRef,
+  matchAnchorWidth,
+  className,
+  children,
+}: {
+  anchorRef: React.RefObject<HTMLElement | null>;
+  dropdownRef?: React.RefObject<HTMLDivElement | null>;
+  matchAnchorWidth?: boolean;
+  className?: string;
+  children: ReactNode;
+}) {
+  const [style, setStyle] = useState<React.CSSProperties>({});
+
+  const updatePosition = useCallback(() => {
+    if (!anchorRef.current) return;
+    const rect = anchorRef.current.getBoundingClientRect();
+    setStyle({
+      position: "fixed",
+      top: rect.bottom + 4,
+      left: rect.left,
+      zIndex: 100,
+      ...(matchAnchorWidth ? { width: rect.width } : {}),
+    });
+  }, [anchorRef, matchAnchorWidth]);
+
+  useLayoutEffect(() => {
+    updatePosition();
+    window.addEventListener("scroll", updatePosition, true);
+    window.addEventListener("resize", updatePosition);
+
+    const anchor = anchorRef.current;
+    let ro: ResizeObserver | undefined;
+    if (anchor) {
+      ro = new ResizeObserver(updatePosition);
+      ro.observe(anchor);
+    }
+
+    return () => {
+      window.removeEventListener("scroll", updatePosition, true);
+      window.removeEventListener("resize", updatePosition);
+      ro?.disconnect();
+    };
+  }, [updatePosition, anchorRef]);
+
+  return createPortal(
+    <div ref={dropdownRef} style={style} className={className}>
+      {children}
+    </div>,
+    document.body
+  );
+}
