+import { onMounted, onUnmounted, ref, watch } from "vue";
+import { useI18n } from "vue-i18n";
+import ProjectSwitchModal from "@/components/Project/ProjectSwitch/ProjectSwitchModal.vue";
+
+const { locale } = useI18n();
